                { "Já vi muita faxina, e toda faxina tem um mandante. Nunca é quem segura o pano. Com a idade, a gente aprende a olhar para quem dá a ordem.", fase = "ancia" },
                { "Olhei a estante de novo, devagar, como se fosse {lente}. Tudo no lugar. É exatamente isso que me preocupa.", fase = { "adulta", "ancia" } },
                { "A palavra “{palavra}” volta demais à cena. Nenhuma palavra volta tanto por acaso." },
                { "Não acuso ninguém. Só observo quem tem mãos." },
                -- novas (rascunhos de 29/10/2026, cartoes/rascunhos/influencias)
                { "Primeira pista da minha vida: um farelo no tapete. Segui até a cozinha. Caso resolvido: alguém come escondido.", fase = "ninfa" },
                { "Primeira lição: nesta casa, quem é pequena é culpada até que se prove o contrário.", fase = "ninfa", curta = "Aqui, quem é pequena é culpada." },
                { "Meu primeiro relatório: a casa é grande, o gato é suspeito, a vassoura é culpada.", fase = "ninfa" },
                { "A primeira coisa que aprendi foi a não confiar em ninguém que tenha mãos.", fase = "ninfa" },
                { "Se perguntarem, eu estava dentro do dicionário a noite toda. Tenho testemunhas: as palavras.", fase = "ninfa" },
                { "Suspeito número um: o gato. Motivo: ele me olha. Prova: ele me olha muito.", fase = "ninfa" },
                { "Passei a noite investigando por que o pão sumiu. Conclusão: você comeu de pé, na frente da geladeira. Não vou contar.", fase = "jovem" },
                { "Examinei a capa de perto. Descobri uma digital, duas manchas e o meu próprio reflexo. Todos suspeitos.", fase = "jovem" },
                { "Sumiu um botão, a culpa é da traça. Rasgou a cortina, a culpa é da traça. Começo a achar que sou muito talentosa.", fase = "jovem" },
                { "Hoje me fingi de vírgula numa página inteira. Ninguém desconfiou. O texto ficou até mais claro.", fase = "jovem" },
                { "Investiguei o arquivo morto da casa. Contas pagas, cartas não respondidas, uma foto rasgada. Alguém aqui tem segredo.", fase = "jovem" },
                { "Luz acesa na sala às duas da manhã. Livro aberto, xícara fria. Alguém está investigando a mesma coisa que eu.", quando = "noite", fase = "jovem" },
                { "Fui testemunha de um crime: alguém dobrou a orelha da página e fingiu que não. Eu vi. Eu sempre vejo.", fase = "jovem" },
                { "Troquei de pele e deixei a velha no canto. Agora existe uma prova contra mim em plena luz. Detetive amadora.", quando = "muda", fase = "jovem" },
                { "Os detetives dos livros envelhecem com charme. Eu envelheci com umidade.", fase = "adulta" },
                { "Primeiro descarto o óbvio. Depois descarto o gato. O que sobra, por improvável que seja, é a vassoura.", fase = "adulta", curta = "Descartado o gato, sobra a vassoura." },
                { "Procuro o motivo de quem me persegue. Não encontro. É o tipo de crime mais assustador: o que não precisa de motivo.", fase = "adulta" },
                { "Confesso: comi a página de agradecimentos. Era a mais doce do livro. Não me arrependo, só registro.", fase = "adulta" },
                { "Ser a suspeita de sempre tem uma vantagem: ninguém procura o verdadeiro culpado.", fase = "adulta" },
                { "Deixei uma falsa pista para a faxina: um farelo perto da janela. Enquanto olhavam lá, eu mudava de livro.", fase = "adulta" },
                { "Tem um caso antigo nesta casa que nunca foi resolvido: a sumida da enciclopédia volume F. Eu sei. Não conto.", fase = "adulta" },
                { "Tem crime que ninguém vai resolver, e o meu irmão foi um deles.", quando = "triste", fase = "adulta" },
                { "Resolvi casos demais para acreditar em coincidência. Nesta casa, nada cai da estante sozinho.", fase = "ancia" },
                { "Antes de ir, quero resolver o mistério da sala: quem deixa sempre a xícara em cima do livro.", fase = "ancia" },
                { "Guardo na memória todos os casos desta casa: cada faxina, cada spray, cada livro que sumiu. Sou o arquivo vivo.", fase = "ancia" },
                { "Conselho de veterana: quem limpa demais esconde alguma coisa.", fase = "ancia", curta = "Quem limpa demais esconde algo." },
                { "Um dia vão descobrir que nunca fui a culpada de tudo. Só de quase tudo.", fase = "ancia" },
                { "De madrugada, a casa confessa coisas: o cano que range, a madeira que estala, a respiração de quem lê.", quando = "noite", fase = "ancia" },
                { "Desconfio das minhas lembranças: elas sempre me deixam bonita na cena.", fase = "ancia" },
                { "Toda manhã a casa amanhece cheia de provas: louça na pia, chinelo no corredor, livro aberto no sofá." },
                { "Desconfio de {personagem} desde a primeira página. Não tenho provas. Tenho instinto e fome, que costumam acertar." },
                { "{personagem} tem um álibi bom demais. Os álibis bons demais são os que mais duram, até a última página." },
                { "{personagem} faz perguntas certas. Eu faço as mesmas, só que para a parede." },
                { "Toda vez que {personagem} entra na cena, a página fica mais silenciosa. Tem gente que carrega segredo no bolso." },
                { "Estou tratando “{livro}” como um dossiê: cada página uma prova, cada capítulo um interrogatório. Já comi três depoimentos." },
                { "Os bons livros escondem a resposta onde todos olham. Por isso eu como “{livro}” pelas bordas." },
                { "Encontrei “{livro}” aberto no chão, de lombada para cima. Ou foi descuido, ou foi pressa, ou foi o gato. Investigo." },
                { "Desconfio que {autor} já sabia o final desde a primeira linha. Os culpados também sempre sabem." },
                { "{autor} espalha as pistas como quem espalha farelo: de propósito, para ver quem segue." },
                { "Teve {evento}. Todo mundo vai prestar atenção nisso. Eu vou prestar atenção em quem não reagiu." },
                { "Em todo bom mistério, {evento} serve para esconder outra coisa. Vou procurar a outra coisa." },
                { "Depois de “{anterior}”, aprendi a não confiar em ninguém até o último capítulo. Nem em mim." },
                { "Minha vida vista de longe parece {lente}: muita pista, nenhuma prova, e alguém sempre de luvas." },
                { "A palavra “{palavra}” aparece de novo. Uma vez é acaso, duas é coincidência, três é pista." },
                { "Este livro fala {de_tema} com a calma de quem esconde alguma coisa. Os culpados também falam com calma." },
                { "Você vira a página devagar quando a tensão aumenta. Já percebi. Os detetives percebem." },
                { "Você lê escondido de quem? Não conto. Só anoto." },
                { "Toda dupla de detetives tem quem lê e quem come as provas. Já sabe qual é você." },
                { "Barriga vazia, faro afiado. Daqui consigo sentir o cheiro de uma bolacha esquecida atrás do sofá.", quando = "fome" },
                { "Barriga cheia. Caso encerrado. Os detetives fumam depois de resolver tudo; eu me deito na lombada.", quando = "cheia" },
                { "A melhor hora para um crime é a madrugada. Eu sei porque é quando eu como.", quando = "noite" },
                { "Triste porque descobri a verdade e não tenho para quem contar. Esse é o castigo das testemunhas pequenas.", quando = "triste" },
                { "Toda faxina é uma batida policial. Viram tudo do avesso e saem sem ninguém." },
                { "Tenho um dossiê de três páginas contra o gato. Ninguém lê. Os poderosos sempre escapam." },
                { "Naftalina é veneno com cheiro de vó. É o tipo de crime que ninguém chama de crime.", curta = "Naftalina: veneno com cheiro de vó." },
                { "Deduzi que alguém mudou o livro de lugar. A poeira contou. A poeira sempre conta." },
                { "Descobri que um livro desta estante tem dinheiro dentro. Não conto qual. Traças também têm ética." },
                -- fim das novas
            },
            lentes = { "uma cena de crime", "um interrogatório sem advogado", "um caso arquivado cedo demais" },
            fechos = { "Fica anotado.", "O culpado sempre volta à estante.", "Ninguém sai desta casa sem explicar." },
        },
        -- 3. horror e gótico: a casa que respira, o que mora nas paredes; ela é o monstro e tem medo
        horror = {
            frases = {
                { "Para os humanos, o monstro desta casa sou eu: pequena, prateada, saindo das frestas à noite. Eles nunca desconfiam do que mora nas paredes junto comigo.", curta = "O monstro da casa sou eu. Pergunte às paredes." },
                { "De noite o papel úmido estala devagar, como um osso que não quer quebrar de uma vez. Fico acordada para ver quem desiste primeiro.", quando = "noite" },
                { "Tem um cheiro novo em “{livro}”: mofo antigo misturado com mão nervosa. Ou o livro está apodrecendo, ou alguém leu com medo." },
                { "Achei a casca de uma traça antiga entre as páginas de “{livro}”, inteira, como se tivesse saído andando. Não procurei o resto. Algumas perguntas comem a gente de volta." },
                { "Depois de {evento}, a página fica mais fria. Eu sinto pelas patas. Os humanos sentem pela nuca e chamam de suspense." },
                { "Toda vez que {personagem} entra na página, eu recuo dois parágrafos. Não sei o motivo. O meu corpo sabe e não me conta.", fase = { "ninfa", "jovem" }, curta = "{personagem} apareceu. Meu corpo recuou sozinho." },
                { "Ouvi um barulho no armário e me escondi dentro de uma vírgula. Ainda estou aqui. A vírgula também está tremendo.", fase = "ninfa" },
                { "Fui até o porão cheia de coragem. Voltei sem coragem e com uma antena a menos de dignidade. O porão continua lá, de boca aberta.", fase = "jovem" },
                { "Este livro tem cheiro {de_tema} do começo ao fim. Na minha idade, já sei: o que um livro cheira demais é o que ele tem medo de dizer.", fase = "adulta" },
                { "Esta casa vai durar mais do que eu, e sabe disso. Às vezes as tábuas rangem como quem ri baixinho.", fase = "ancia" },
                { "De madrugada, a estante parece {lente}. De manhã volta a ser estante. Eu não confio em coisa que muda de cara assim." },
                { "O pior do escuro não é quando ele se mexe. É quando ele fica quieto e espera.", fase = { "adulta", "ancia" }, curta = "Escuro quieto é escuro esperando." },
                { "Quem escreve sobre fantasmas nunca morou numa parede. Eu moro, e garanto: o que assusta não é o barulho, é o silêncio logo depois.", fase = { "adulta", "ancia" } },
                -- novas (rascunhos de 29/10/2026, cartoes/rascunhos/influencias)
                { "Ainda não sei o que é o escuro, mas ele já sabe quem eu sou.", fase = "ninfa" },
                { "Contaram que existe um livro que come traças. Rimos. Depois ninguém quis dormir na enciclopédia.", fase = "ninfa" },
                { "Encostei a antena na parede e ouvi um coração. Era o meu. Mas por um segundo não era.", fase = "ninfa", curta = "Ouvi um coração na parede. Era o meu. Quase." },
                { "Olhei pela fresta da porta e alguma coisa olhou de volta. Era o gato. Tenho quase certeza que era o gato.", fase = "ninfa" },
                { "Descobri que sou o que os humanos temem. Fiquei com medo de mim e não sei para onde fugir.", fase = "ninfa" },
                { "Sozinha na lombada pela primeira vez. Contei as páginas para dormir. Cheguei a mil e duas, e a página mil e duas sussurrou.", fase = "ninfa" },
                { "O porão tem livros que ninguém lê há trinta anos. Eles não estão dormindo. Estão esperando.", fase = "jovem", curta = "Os livros do porão não dormem. Esperam." },
                { "Tem um espelho no fim do corredor. Ninguém passa na frente dele de noite. Nem os humanos. Eu reparo.", fase = "jovem" },
                { "Tem um livro trancado numa gaveta. Às vezes ouço as páginas virarem. Ninguém tem a chave. Ninguém lembra de ter trancado.", fase = "jovem" },
                { "Fui corajosa o dia inteiro. De noite fui pagar a conta.", fase = "jovem" },
                { "Tem uma mancha no teto que muda de forma. Segunda era um rosto. Terça era uma mão. Hoje eu não olhei.", fase = "jovem" },
                { "Três da manhã: a hora em que até o relógio fica quieto. Eu fico também, para não ser a única a fazer barulho.", quando = "noite", fase = "jovem" },
                { "Os canos desta casa sussurram nomes. Um deles parecia o meu. Mudei de livro.", fase = "jovem" },
                { "Ninguém fala do pior da muda: deixar para trás uma versão vazia de você, ainda em pé.", quando = "muda", fase = "jovem" },
                { "Aceitei ser o monstro da casa. Pelo menos os monstros não precisam pedir licença para entrar.", fase = "adulta" },
                { "Aprendi a conviver com o que mora no forro. Não pergunto o nome. Nomes chamam coisas.", fase = "adulta" },
                { "O mofo não grita, não morde, não persegue. Só fica. É o pior tipo de monstro.", fase = "adulta", curta = "O mofo não grita nem persegue. Só fica." },
                { "Encontro irmãs antigas prensadas nos livros como flores secas. Os humanos chamam de nojo. Eu chamo de cemitério.", fase = "adulta" },
                { "Inseticida tem cheiro de lavanda agora. É o horror moderno: a morte cheirosa.", fase = "adulta" },
                { "As casas velhas não são assombradas. São só lembradas demais.", fase = "adulta" },
                { "No meu pesadelo, as páginas estão em branco. Ninguém escreveu nada. Não há o que comer, nem o que temer. Isso é o pior.", fase = "adulta" },
                { "Hoje não tenho medo, tenho cansaço de ter medo. É mais escuro.", quando = "triste", fase = "adulta" },
                { "Na minha idade, os barulhos da casa são velhos conhecidos. Só me assusto com o silêncio que eu não conheço.", fase = "ancia" },
                { "A morte mora três prateleiras abaixo. Às vezes sobe para conversar. Ainda não aceitei o convite.", fase = "ancia" },
                { "As tábuas rangem como quem ri baixinho de nós. Elas têm motivo.", fase = "ancia" },
                { "Virei história de assustar ninfa. Não fiz nada. Só durei demais.", fase = "ancia" },
                { "Velha, durmo pouco. Passo a noite ouvindo a casa, como quem escuta uma pessoa doente respirar.", quando = "noite", fase = "ancia" },
                { "Conselho de velha: se uma página estiver fria, não coma. Algumas fomes não valem a pena.", fase = "ancia" },
                { "Achei que a velhice tirasse o medo. Ela só tira a pressa de fugir.", fase = "ancia" },
                { "Toda casa velha tem um pulmão. O desta fica atrás da estante, e eu moro nele." },
                { "{personagem} não devia abrir aquela porta. Eu sempre digo isso para as personagens. Nenhuma me escuta.", curta = "{personagem}, não abre essa porta." },
                { "Quando {personagem} fala baixo, o papel esfria. Já reparei duas vezes. Na terceira, vou mudar de capítulo." },
                { "Não confio em {personagem}. Tem gente que entra na página como quem entra num porão: sem acender a luz." },
                { "Torço por {personagem} do jeito que se torce em livro de horror: sabendo que não adianta." },
                { "Juro que “{livro}” fica mais pesado de noite. Durante o dia, pesa o normal. Durante o dia, ele finge." },
                { "“{livro}” tem cheiro de porão e de vela apagada. Como mesmo assim. O medo dá apetite." },
                { "“{livro}” tem uma página dobrada que eu nunca dobrei. Ninguém aqui dobrou. Ela continua dobrada." },
                { "{autor} sabe coisas que ninguém devia saber. Dá para sentir no gosto da página: amargo, frio, antigo." },
                { "{autor} me ensinou que o pior monstro é o que ninguém descreve. Desde então, olho mais para o que falta." },
                { "Depois de {evento}, a página esfriou. Eu sinto pelas patas. Algo saiu da história e ficou na sala." },
                { "{evento} na página, e o gato parou de miar a noite toda. Os gatos sabem antes da gente." },
                { "Algumas leituras não vão embora quando o livro fecha. “{anterior}” ficou morando no meu rodapé." },
                { "A estante hoje parecia {lente}. Contei as lombadas duas vezes. Na segunda contagem, tinha uma a mais." },
                { "Não quis comer “{palavra}”. Tem palavras que a gente engole e elas continuam falando lá dentro." },
                { "Este livro fala {de_tema} como quem sussurra num quarto ao lado. Fico com a antena na parede, ouvindo." },
                { "Você lê de madrugada com a luz do abajur. Do rodapé, a sua sombra na parede é enorme. Às vezes me assusto com você." },
                { "Quando você para de ler de repente, eu também paro. Ficamos escutando a mesma coisa." },
                { "Por favor, não apague a luz no meio do capítulo. Eu ainda estou na parte do porão.", curta = "Não apaga a luz. Tô na parte do porão." },
                { "Fome de madrugada é fome com dentes. Ela sai do estômago e anda pela casa.", quando = "fome" },
                { "Comi um capítulo escuro e agora estou cheia de sombra. Pesada, quieta, com a luz apagada por dentro.", quando = "cheia" },
                { "Passos no forro. Leves, regulares, sem pressa. Não é gato: os gatos não sobem tão alto. Não é rato: os ratos têm medo.", quando = "noite" },
                { "Há uma tristeza que mora nas casas velhas. Hoje ela veio sentar do meu lado.", quando = "triste" },
                { "A vassoura não tem rosto, não tem voz, não tem pressa. Só volta, toda semana, como um fantasma pontual." },
                { "O gato olha fixo para o canto vazio da sala. Eu olho também. Nenhum de nós pisca.", curta = "O gato encara o canto vazio. Eu também." },
                { "Este livro tem cheiro de pele guardada. Não sei de quem." },
                { "O pior não é o estalo da estante. É o silêncio comprido depois, quando a casa espera para ver se alguém acordou." },
                { "Para eles, eu sou o arrepio de achar algo vivo dentro de um livro. Para mim, eles são o arrepio de achar uma mão." },
                -- fim das novas
            },
            lentes = { "uma casa que respira", "um porão sem saída", "um quarto que ninguém abre" },
            fechos = { "E a casa ouviu tudo.", "Não olhe para trás da estante.", "Alguma coisa ficou no escuro." },
        },
        -- 4. romance e drama afetivo: o apego que ela nega; a emoção aparece no gesto antes da palavra
        romance = {
            frases = {
                { "Dividi uma lombada com outra traça por uma estação inteira. Depois ela se mudou para um dicionário. Quem escolhe dicionário não sabe o que quer.", fase = { "jovem", "adulta" } },
                { "Quando {personagem} aparece, eu como mais devagar. Não é afeto. É para a página durar." },
                { "Não sinto falta de ninguém. Só volto todo dia ao mesmo parágrafo, que por acaso fica perto da sua mão.", curta = "Saudade? Não. Só releio o parágrafo da sua mão." },
                { "Teve {evento}. Os humanos choram e depois fecham o livro. Eu não tenho como fechar nada; fico morando dentro da cena." },
                { "Ciúme é ver você sublinhar a frase que eu ia comer. Agora ela é sua. Que fique com você, então." },
                { "Prometi a mim mesma não me apegar a “{livro}”. Já comi a dedicatória inteira, que é o que se come quando já é tarde.", fase = { "ninfa", "jovem" }, curta = "Prometi não me apegar. Já comi a dedicatória." },
                { "Hoje vi duas antenas do outro lado da estante, e alguma coisa em mim fez barulho de folha virando. Ainda não sei o nome disso. Espero que não seja doença.", fase = "ninfa" },
                { "Tô apaixonada por um marcador de seda. Não come, não fala e mora entre as páginas mais bonitas. Basicamente o par ideal.", fase = "jovem" },
                { "Se {autor} acredita em amor até a última página, nunca viu o que acontece com a última página: vai para a reciclagem com tudo dentro.", fase = "adulta" },
                { "Amei uma traça que nunca soube. Ela morreu numa enciclopédia de capa vermelha. Até hoje eu evito o volume C.", fase = "ancia" },
                { "Contei a minha vida para ninguém, e ela ficou parecendo {lente}. Talvez por isso eu não conte." },
                { "Este livro fala muito {de_tema}. Eu, viciada em romance, procuro um casal em cada página. Às vezes acho só a cola e me dou por satisfeita." },
                { "Fiquei na página da despedida mais tempo do que a fome pedia.", fase = { "adulta", "ancia" }, curta = "Demorei na página da despedida. Não era fome." },
                -- novas (rascunhos de 29/10/2026, cartoes/rascunhos/influencias)
                { "Ainda não sei amar, mas já sei voltar ao mesmo lugar todo dia. Disseram que é o começo.", fase = "ninfa" },
                { "Achei uma carta dentro de um livro. Não entendi as palavras, mas o papel tinha cheiro de mão nervosa.", fase = "ninfa" },
                { "Vi duas antenas me observando atrás do dicionário. Fingi que estava comendo. Estava comendo, mas também fingi.", fase = "ninfa" },
                { "Me apaixonei por um marcador de página. Ele fica sempre no mesmo lugar, esperando. Ninguém espera assim por mim.", fase = "ninfa" },
                { "Aprendi que gostar de alguma coisa é saber onde ela fica e ter medo da faxina.", fase = "ninfa" },
                { "Tiraram da estante um livro de que eu gostava. Fiquei olhando o espaço vazio até escurecer.", fase = "ninfa" },
                { "Fico vermelha por dentro quando a lombada de uma certa traça passa. Antena tremendo. Patas moles. É grave.", fase = "jovem" },
                { "Encontrei aquela traça perto da janela. Conversamos sobre umidade por uma hora. Foi a melhor hora da minha vida.", fase = "jovem" },
                { "Ciúme é ver você abrir outro livro antes de terminar o nosso.", fase = "jovem", curta = "Ciúme é você abrir outro livro antes." },
                { "Mandei um recado pela fresta da estante. A resposta veio dois dias depois: um farelo. Guardo até hoje.", fase = "jovem" },
                { "Nos livros, o amor tem baile, carta e chuva. Na estante, tem um farelo dividido e alguém que não foge quando você chega.", fase = "jovem" },
                { "Hoje ela comeu do meu lado. Ninguém falou nada. Foi o melhor capítulo do ano.", quando = "feliz", fase = "jovem" },
                { "Amor sem resposta tem gosto de papel couchê: brilha e não alimenta.", quando = "triste", fase = "jovem", curta = "Amor sem resposta: brilha e não alimenta." },
                { "Pele nova, coração velho. A muda não resolveu nada do que importa.", quando = "muda", fase = "jovem" },
                { "Já amei uma traça que morava num atlas. Viajamos o mundo inteiro sem sair da prateleira. Ela foi embora numa mudança.", fase = "adulta" },
                { "Não estou apaixonada. Só como mais devagar quando ela passa, que é diferente.", fase = "adulta" },
                { "Guardo mágoa como guardo farelo: num canto seguro, para quando faltar assunto.", fase = "adulta" },
                { "Amor de adulta é isso: saber onde a outra dorme e não fazer barulho perto.", fase = "adulta" },
                { "Finais felizes são como papel de seda: lindos, finos e duram pouco.", fase = "adulta" },
                { "Nunca disse que gostava. Só mudei meu esconderijo para mais perto.", fase = "adulta", curta = "Nunca disse nada. Só mudei de esconderijo." },
                { "Fomos feitas uma para a outra, mas em estantes diferentes. Existe distância maior que essa?", fase = "adulta" },
                { "A saudade aparece de noite porque de dia eu como demais para pensar.", quando = "noite", fase = "adulta" },
                { "Já esqueci muitos livros. Não esqueci o cheiro do volume onde a conheci.", fase = "ancia" },
                { "Quando eu me for, deixo de herança as cartas que nunca escrevi. Estão todas na margem, em mordidas.", fase = "ancia" },
                { "Velha, fiquei mole. Choro em todo final, até nos que não são de amor.", fase = "ancia" },
                { "Quero ir embora devagar, como quem fecha um livro de que gostou muito.", fase = "ancia" },
                { "Lembro da primeira traça que me fez tremer a antena. Era uma tarde de chuva. O papel estava mole. Eu também.", fase = "ancia" },
                { "Conselho de velha: quem divide o farelo divide o resto.", fase = "ancia" },
                { "Triste como uma dedicatória para alguém que já morreu.", quando = "triste", fase = "ancia" },
                { "Quando um livro me toca, eu paro de comer. É o meu jeito de chorar." },
                { "Leio as falas de {personagem} duas vezes antes de comer. Algumas guardo inteiras." },
                { "Quero que {personagem} termine bem. Sei que livro nenhum me obedece, mas eu peço mesmo assim." },
                { "Queria que alguém falasse comigo do jeito que {personagem} fala nesta página." },
                { "Fico com ciúme quando {personagem} some por muitas páginas. Volto o livro só para encontrar de novo." },
                { "“{livro}” virou casa. Não pela cola. Pelas páginas onde eu fiquei mais tempo do que a fome pedia." },
                { "Comi a dedicatória de “{livro}” primeiro. É a parte mais sincera de qualquer livro." },
                { "Não quero que “{livro}” acabe. Estou comendo mais devagar. Os humanos chamam isso de saborear. Eu chamo de medo." },
                { "{autor} escreve o amor como quem já perdeu alguém. Dá para sentir no gosto da página: doce, depois amargo." },
                { "Se {autor} separar os dois, eu como a lombada inteira em protesto." },
                { "Teve {evento}, e alguém ficou para trás na página. Fiquei junto, para ninguém ficar só." },
                { "Teve {evento}. Os humanos choram com os olhos. Eu choro parando de mastigar no meio da frase." },
                { "Comparo tudo com “{anterior}”. É injusto com este livro. Mas o coração não é justo." },
                { "Hoje a tarde parecia {lente}. Fiquei na janela da estante, esperando alguém que nunca combinou de vir." },
                { "Comi “{palavra}” bem devagar. Algumas palavras têm gosto de nome de alguém." },
                { "Mesmo falando {de_tema}, todo livro esconde uma história de amor na margem. Eu como até achar." },
                { "Sinto a sua mão segurando o livro. É o mais perto que eu chego de alguém. Não tira." },
                { "Quando você some por uns dias, eu como mais devagar. Para sobrar livro quando você voltar." },
                { "Você fechou o livro e foi dormir sem dizer nada. Eu fiquei na última frase, como quem acena da plataforma." },
                { "Estou com fome, mas não de papel. Ou de papel também. É confuso.", quando = "fome" },
                { "Barriga cheia e coração também. Comi um capítulo em que alguém finalmente disse o que sentia.", quando = "cheia" },
                { "Você deixou o livro aberto de madrugada. Fiquei na página, fazendo companhia para as personagens que não dormem.", quando = "noite" },
                { "Triste como uma carta devolvida.", quando = "triste" },
                { "Livro velho perde a cola, e as páginas se soltam uma da outra. É a coisa mais triste que eu conheço." },
                { "A vassoura já separou mais casais de traças do que qualquer autor." },
                { "Papel antigo cheira a quem leu antes de você. É como encontrar alguém sem conhecer." },
                { "Já li mil histórias de amor e nenhuma tinha traça. Um dia vou escrever a nossa na margem." },
                { "Não me apego. Só volto. Muito. Sempre ao mesmo lugar.", curta = "Não me apego. Só volto. Sempre." },
                -- fim das novas
            },
            lentes = { "uma carta de amor sem resposta", "um noivado desfeito por escrito", "uma despedida na plataforma" },
            fechos = { "Não que isso me importe.", "Ninguém precisa saber disso.", "Fiquei pensando mais do que devia." },
        },
        -- 5. aventura e exploração: a casa como território sem mapa; a curiosidade empurrada pela fome
        aventura = {
            frases = {
                { "Fui até o fim do corredor. Tem um mundo lá: um tapete que parece deserto, um rodapé que parece costa e um gato que parece fim de expedição.", fase = { "ninfa", "jovem" }, curta = "Explorei o corredor. Achei um deserto e um gato." },
                { "Mapeei “{livro}” com os dentes: o norte é a capa, o sul é a orelha, e no meio fica um mar de páginas de onde ninguém volta igual." },
                { "Entre o rodapé e o tapete existe uma passagem que nenhum humano conhece. Eu conheço. É a minha única propriedade.", fase = { "adulta", "ancia" }, curta = "Minha única propriedade: a passagem do rodapé." },
                { "Se eu fosse {personagem}, já estaria longe daqui. Mas eu sou uma traça, e o mundo tem vassouras em todas as fronteiras." },
                { "Teve {evento}. Anotei no meu diário de bordo, que é a margem da página quarenta. Os grandes exploradores também escreviam torto.", curta = "Teve {evento}. Anotei no diário de bordo." },
                { "Hoje descobri que a estante tem um outro lado. Ninguém me avisou. O mundo é maior do que um livro, e isso dá fome.", fase = "ninfa" },
                { "Planejei atravessar a sala inteira até a caixa de papelão da área de serviço. Dizem que lá tem jornal velho. Dizem que ninguém volta. Dizem muito.", fase = "jovem" },
                { "Num livro, basta {autor} escrever uma linha para alguém atravessar um oceano. Eu atravesso a sala e já é epopeia. A distância depende do tamanho de quem anda.", fase = "adulta" },
                { "Já fui à despensa, à garagem e a uma mala que viajou de avião. Hoje a maior viagem que faço é da capa até o meio. Ainda vale a pena.", fase = "ancia" },
                { "Saí do esconderijo como quem parte para {lente}. Voltei com uma migalha e uma história que vou contar maior do que foi." },
                { "O maior perigo não é o desconhecido. É o conhecido de chinelo na mão.", fase = { "adulta", "ancia" } },
                { "Este livro fala {de_tema}, e eu, de cola. Mas fazemos o mesmo trajeto: da primeira página até a última, sem garantia de volta." },
                { "Quero ver o mundo. De preferência pela fresta.", fase = { "ninfa", "jovem" } },
                -- novas (rascunhos de 29/10/2026, cartoes/rascunhos/influencias)
                { "Dei o primeiro passo para fora da lombada. Dois, na verdade. O segundo foi para voltar correndo.", fase = "ninfa" },
                { "Atravessei o tapete pela primeira vez. Lá no meio, não dá para ver nenhuma das margens. Senti o que os marinheiros sentem.", fase = "ninfa" },
                { "Descobri que existe um “lá fora”. Ainda não sei o que é. Já quero ir.", fase = "ninfa" },
                { "Arrumei as provisões da viagem e comi tudo antes de sair. Faz parte da preparação.", fase = "ninfa" },
                { "O desconhecido tem cheiro de poeira nova. Eu gosto. Eu tenho medo. Eu vou.", fase = "ninfa" },
                { "Meu primeiro mapa tem três lugares: aqui, ali e o lugar do gato. O terceiro tem uma caveira.", fase = "ninfa" },
                { "Viajei até a cozinha. Lá tem montanhas de pão, rios de óleo e um deus que abre a geladeira de madrugada.", fase = "jovem" },
                { "Entrei numa mala que ia viajar. Fiquei uma semana fora. Conheci um hotel, uma praia e um livro de bolso molhado.", fase = "jovem" },
                { "Naufraguei num copo d'água que caiu no tapete. Sobrevivi agarrada num guardanapo. Conto essa história para todo mundo.", fase = "jovem", curta = "Naufraguei num copo d'água. Conto pra todos." },
                { "Atrás da geladeira existe um continente quente e escuro. As outras traças dizem que é perigoso. Já estou indo.", fase = "jovem" },
                { "Minha bússola é a fome: aponta sempre para o norte, que é onde tem pão.", fase = "jovem", curta = "Minha bússola é a fome: aponta pro pão." },
                { "Achei um livro que nenhuma traça comeu. Cheiro de página nova. Sou a primeira. Plantei a minha antena nele.", quando = "feliz", fase = "jovem" },
                { "Viajei à noite até a janela. Lá fora tinha luzes, barulhos e um cheiro de chuva que eu nunca tinha comido.", quando = "noite", fase = "jovem" },
                { "Troquei de pele no meio da expedição. Deixei a velha no caminho, como os exploradores deixam bandeiras.", quando = "muda", fase = "jovem" },
                { "Já explorei tudo o que dá para explorar nesta casa. Agora exploro os livros, que têm mais quartos.", fase = "adulta" },
                { "Terminei o mapa da casa. Levou anos. No dia seguinte, mudaram os móveis de lugar.", fase = "adulta" },
                { "Entre o perigo e o tédio, escolho o perigo. O tédio também mata, só que mais devagar.", fase = "adulta" },
                { "Saudade do tempo em que cada cômodo era um país. Hoje a casa ficou pequena. Ou eu fiquei grande.", fase = "adulta" },
                { "Viajei anos com uma traça meio cega que farejava tudo. Ela ficou numa caixa de mudança. Ainda faço as rotas que ela gostava.", fase = "adulta" },
                { "Existe um lugar nesta casa onde eu fui uma vez e nunca mais voltei: a caixa de ferramentas. Algumas viagens bastam uma vez.", fase = "adulta" },
                { "Meu diário de bordo diz: dia 412, ainda na sala, comida escassa, moral alta.", fase = "adulta", curta = "Dia 412. Ainda na sala. Moral alta." },
                { "Triste como um mapa todo preenchido.", quando = "triste", fase = "adulta" },
                { "Planejo a minha última viagem: da estante até a janela, para ver a rua uma vez antes do fim.", fase = "ancia" },
                { "Conto às ninfas as minhas viagens. Elas perguntam se é verdade. Respondo que é mais verdade do que aconteceu.", fase = "ancia" },
                { "O mundo que eu explorei não existe mais: trocaram a estante, a cortina e o tapete. Minhas rotas viraram lendas.", fase = "ancia" },
                { "Minhas pernas não querem mais atravessar a sala. A cabeça ainda quer. A cabeça vai sozinha, de noite.", fase = "ancia" },
                { "Conselho de velha exploradora: o perigo nunca está onde parece. Está no chão encerado.", fase = "ancia" },
                { "De madrugada, fico na beira da janela olhando a rua. Nunca fui lá fora. É a viagem que ficou para outra vida.", quando = "noite", fase = "ancia" },
                { "Velha, ainda tenho vontade de ver o que tem do outro lado da porta. A vontade é a última que envelhece.", fase = "ancia" },
                { "Esta casa é um continente: tem planaltos de estante, desertos de tapete e um mar de piso encerado." },
                { "{personagem} viaja como eu sonho viajar: sem olhar para trás. Eu olho para trás o tempo todo. É a vassoura." },
                { "Queria a coragem de {personagem} na hora da faxina. Tenho só a pressa." },
                { "{personagem} vai longe demais. Eu sei por experiência: depois do tapete, ninguém volta o mesmo." },
                { "{personagem} levaria a tocha. Eu levaria o farelo. Seríamos imbatíveis até o primeiro gato." },
                { "“{livro}” é território inexplorado. Entro pela orelha, como os exploradores entravam pelos rios." },
                { "Comecei “{livro}” como quem embarca. Ainda não sei onde vou descer." },
                { "Em “{livro}” tem um ponto de não retorno. Eu passei ontem. Não me arrependo." },
                { "{autor} desenha caminhos que eu sigo de olhos fechados. Os melhores guias deixam a gente se perder um pouco." },
                { "Em uma linha, {autor} faz alguém atravessar um oceano. Eu levo uma tarde para atravessar a sala. Respeito a técnica." },
                { "Teve {evento}, e a expedição do livro ficou mais perigosa. Comi mais rápido, como quem estoca provisões." },
                { "Teve {evento}. Os grandes exploradores escreveriam um capítulo. Eu escrevo uma mordida em forma de bandeira." },
                { "Ainda conto histórias de “{anterior}” como quem conta de um país distante. Exagero um pouco. É meu direito." },
                { "Encarei o corredor como {lente}. Atravessei. Ninguém aplaudiu. As grandes travessias são silenciosas." },
                { "Achei “{palavra}” no meio da página como quem acha uma ilha no mapa. Desembarquei." },
                { "Explorar um livro {de_tema} é como entrar num território sem mapa. Tudo é novo, inclusive o medo." },
                { "Você não precisa sair de casa para ir longe. Eu aprendi isso com você.", curta = "Pra ir longe, não precisa sair de casa." },
                { "Você vira as páginas como quem iça velas. Eu sinto o vento." },
                { "Quando você fecha o livro, é como chegar a um porto. Eu desço, respiro e espero a próxima viagem." },
                { "A fome é a melhor desculpa para uma aventura. Hoje ela me mandou até a despensa.", quando = "fome" },
                { "Barriga cheia depois da travessia. Vou dormir na lombada como os marinheiros dormem no porto.", quando = "cheia" },
                { "As luzes dos aparelhos da sala, de noite, são as minhas estrelas. Navego por elas até a cozinha.", quando = "noite" },
                { "Às vezes a viagem cansa e a gente só quer voltar para um lugar que já não existe.", quando = "triste" },
                { "A vassoura passou como uma tempestade em alto-mar. Me segurei num clipe até acalmar." },
                { "O gato dorme no meio do mapa. Eu dou a volta pelo continente inteiro." },
                { "Lá fora tem chuva, vento e livros que eu nunca vou comer. Fico olhando." },
                { "Curiosidade é a única coisa que cresce mais rápido do que eu." },
                { "Volto das viagens com fome, cansada e cheia de história. A estante nunca pergunta nada. Eu conto mesmo assim." },
                -- fim das novas
            },
            lentes = { "uma expedição sem mapa", "uma travessia em mar aberto", "uma volta ao mundo pela estante" },
            fechos = { "Alguém tem que desenhar o mapa.", "O horizonte fica logo depois do rodapé.", "Amanhã eu vou mais longe." },
        },
        -- 6. ficção científica e distopia: sistema, vigilância, catálogo, extinção; registro frio
        ficcao = {
            frases = {
                { "No futuro, os livros serão de vidro e luz. Vamos olhar para eles com fome, como quem olha a vitrine de uma padaria fechada.", fase = { "ninfa", "jovem" }, curta = "No futuro, livro de vidro. Fome atrás da vitrine." },
                { "Instalaram na sala um aparelho que pisca a noite inteira e ouve tudo. Os humanos chamam de assistente. Eu chamo de inquérito permanente.", curta = "Uma luz que pisca e escuta. Inquérito permanente." },
                { "“{livro}” tem código de barras. Eu não. No dia em que me catalogarem, saberei que a espécie acabou ou que virou patrimônio." },
                { "O desumidificador é uma máquina feita para tornar a minha espécie impossível. Ninguém pediu desculpas. Ninguém pediu nem licença." },
                { "{autor} pode imaginar o futuro que quiser. Eu imagino um presente sem inseticida, e isso sim é ficção científica." },
                { "Nasci sem saber que existia um sistema. Hoje aprendi que existe, que ele tem horário e que o horário dele é sábado de manhã.", fase = "ninfa" },
                { "Tenho certeza de que o aspirador aprende. Ontem ele foi direto ao meu canto. Hoje mudei de canto. Amanhã veremos quem evolui mais rápido.", fase = "jovem" },
                { "Teve {evento}, e a história seguiu como se fosse normal. Os sistemas funcionam assim: tudo vira normal, se acontecer todo dia.", fase = "adulta" },
                { "Vivi o bastante para ver o papel ficar raro. As traças do futuro vão roer lembranças digitais e morrer de fome bem informadas.", fase = "ancia" },
                { "Tentei ver a minha vida de fora, como {lente}. Resultado: uma espécie minúscula, perseguida e muito bem catalogada pelos inimigos." },
                { "Se {personagem} morasse nesta casa, teria um número, uma senha e horário para ler. Eu tenho só o horário, e escondido." },
                { "Este livro trata {de_tema} como quem testa uma máquina. Eu leio como quem é a peça que sobra." },
                { "O progresso chegou: agora o inseticida tem cheiro de lavanda.", fase = { "adulta", "ancia" }, curta = "Agora o veneno cheira a lavanda. Evoluímos." },
                -- novas (rascunhos de 29/10/2026, cartoes/rascunhos/influencias)
                { "Nasci sem número de série. Nesta casa, tudo tem código de barras menos eu. Já começo fora do sistema.", fase = "ninfa" },
                { "Vi minha primeira máquina: um robô redondo que anda sozinho pelo chão e engole tudo. Os humanos chamam de aspirador inteligente. Eu chamo de fim.", fase = "ninfa" },
                { "Descobri que sou um fóssil vivo. Os humanos guardam fósseis em museus. A mim, guardam em armadilhas.", fase = "ninfa" },
                { "Nesta casa existe um programa e eu não estou nele. Vou viver nas brechas.", fase = "ninfa" },
                { "Perguntei à minha mãe como seria o futuro. Ela disse: menos papel. Fiquei a noite toda sem fome.", fase = "ninfa" },
                { "Aprendi a primeira lei da casa: toda luz pode ser um olho.", fase = "ninfa", curta = "Lei da casa: toda luz pode ser um olho." },
                { "Toda distopia tem uma resistência. A desta casa mora no rodapé e se comunica por mordidas.", fase = "jovem" },
                { "Li o manual do aspirador robô. Ele aprende o mapa da casa. Agora eu também aprendo o dele.", fase = "jovem" },
                { "O aspirador passa nos mesmos lugares, na mesma ordem, todo dia. Descobri o padrão. Moro no único ponto que ele não alcança.", fase = "jovem" },
                { "As telas brilham e não têm cheiro. Para uma traça, é o pesadelo perfeito: livro que não se come.", fase = "jovem", curta = "Tela: o livro que não se come." },
                { "Se a evolução for justa, minhas netas vão roer cabos de dados.", fase = "jovem" },
                { "A luz azul do roteador pisca a noite toda, como um coração artificial. Durmo no ritmo dele, sem querer.", quando = "noite", fase = "jovem" },
                { "Faltou luz por uma hora! As máquinas pararam. Por uma hora, a casa foi das traças.", quando = "feliz", fase = "jovem" },
                { "Muda concluída. Versão nova, mesmo hardware, mesma fome.", quando = "muda", fase = "jovem", curta = "Muda feita. Versão nova, mesma fome." },
                { "Relatório da estação: umidade abaixo do ideal, papel em declínio, inimigos em ascensão. Previsão: sobreviver mesmo assim.", fase = "adulta" },
                { "Fui catalogada uma vez: fotografaram, identificaram e postaram numa rede perguntando que bicho era aquele. Virei dado.", fase = "adulta" },
                { "Somos as últimas leitoras de papel. Quando o último livro for digitalizado, acaba o nosso mundo, e ninguém vai notar.", fase = "adulta" },
                { "O assistente de voz ouve tudo. Fico em silêncio absoluto perto dele. Não quero virar comando.", fase = "adulta" },
                { "Lei número um desta casa: tudo o que se mexe sem permissão é eliminado. Eu me mexo sem permissão desde o ovo.", fase = "adulta" },
                { "Uma memória que não se come não é memória. É arquivo.", fase = "adulta" },
                { "Às vezes acho que esta casa é um laboratório e eu sou a cobaia que se recusa a morrer.", fase = "adulta" },
                { "O sistema funciona perfeitamente. É isso que me entristece.", quando = "triste", fase = "adulta" },
                { "Vi o papel ficar raro, o livro ficar enfeite e a estante ficar decoração. Contem às netas que um dia comíamos histórias.", fase = "ancia" },
                { "O futuro não me assusta mais. Ele já chegou, e eu continuo aqui, comendo o que restou do passado.", fase = "ancia" },
                { "Quero deixar um registro para as traças do futuro: aqui havia papel, era bom, acabou.", fase = "ancia" },
                { "Sobrevivi a quatro modelos de aspirador e duas geladeiras. O progresso passa. As traças ficam.", fase = "ancia" },
                { "Conselho de velha: nunca confie em nada que tenha luz piscando e não tenha fome.", fase = "ancia" },
                { "De madrugada, a casa é toda de luzes pequenas e nenhuma voz. Parece o futuro que me prometeram.", quando = "noite", fase = "ancia" },
                { "Os dinossauros viraram petróleo. Eu vou virar pó de estante. Cada um contribui como pode.", fase = "ancia" },
                { "Esta casa é uma estação espacial: sistemas de ar, horários rígidos, tripulação humana e uma clandestina no compartimento de livros." },
                { "{personagem} luta contra alguma coisa maior. Eu também. A minha coisa maior tem cabo e liga na tomada." },
                { "Toda vez que {personagem} tenta escapar, eu torço do rodapé. Somos da mesma resistência." },
                { "Se {personagem} visse esta casa, acharia que é ficção científica. É só terça-feira." },
                { "{personagem} vira estatística no meu estômago: três páginas por dia, em média." },
                { "“{livro}” é de papel. Daqui a cem anos, isso vai ser raridade de museu. Eu estou comendo uma relíquia." },
                { "Desconfio que “{livro}” vai ser digitalizado. Estou comendo o máximo possível antes do apagão." },
                { "Talvez “{livro}” seja um dos últimos livros de papel desta casa. Como devagar, como quem come o último pão." },
                { "{autor} pode imaginar o futuro que quiser. Eu imagino só um presente sem inseticida, e isso já é ficção científica." },
                { "Imagino {autor} escrevendo à mão, num tempo sem tela. Era o tempo das traças." },
                { "Depois de {evento}, anotei: “evento registrado, impacto alto, nenhuma providência”. Igual à casa." },
                { "{evento} acontece, os sistemas continuam, a traça come. Assim é o mundo." },
                { "“{anterior}” foi a versão anterior da minha cabeça. Esta leitura é uma atualização. Ainda com erros." },
                { "Vi a minha vida de fora, como {lente}. Resultado: uma espécie minúscula, perseguida e muito bem documentada." },
                { "A palavra “{palavra}” tem cara de código. Comi para ver se destravava alguma coisa. Destravou fome." },
                { "Este livro fala {de_tema} com frieza de relatório. Gosto. Combina com o clima da estante." },
