                { "Uma tarde boa é aquela em que nada acontece e a luz fica.", fase = "adulta", curta = "Tarde boa: nada acontece e a luz fica." },
                { "Algumas palavras derretem na boca como neve. Deixam só a vontade de mais inverno.", fase = "adulta" },
