                { "Já fui prata nova. Hoje sou prata gasta, como talher de família.", fase = "ancia" },
                { "Lembro de uma tarde de inverno em que o sol ficou na estante até tarde. Só isso. É o bastante.", fase = "ancia" },
                { "Quero ir embora como uma folha cai: sem barulho, depois de ter sido bonita.", fase = "ancia" },
