        -- 10. tragédia: destino, queda, ironia trágica; ela sabe o fim e assiste mesmo assim
        tragedia = {
            frases = {
                { "Eu sabia que a vassoura viria. Sabia o dia, a hora e o canto. Saber nunca salvou ninguém; só deixa a gente assistir com mais detalhe.", fase = { "adulta", "ancia" }, curta = "Sabia a hora da vassoura. Só assisti melhor." },
                { "Meu erro fatal é gostar de papel bom. Papel bom fica em estante limpa, estante limpa tem dono atento, e dono atento tem inseticida.", curta = "Meu erro fatal: gostar de papel bom." },
                { "Não sei como termina para {personagem}. Mas conheço o gênero, e o gênero não perdoa quem aparece tanto." },
                { "Teve {evento}. Se houvesse um coro neste livro, diria que avisou. Eu sou o coro. Avisei. Ninguém ouve as traças." },
                { "Fugi do inseticida e caí na naftalina. Os deuses têm senso de humor, e é sempre às minhas custas.", fase = { "ninfa", "jovem" }, curta = "Do inseticida para a naftalina. Os deuses riem." },
                { "Minha mãe me disse que toda traça tem uma última página. Perguntei qual seria a minha. Ela mudou de assunto, e eu entendi.", fase = "ninfa" },
                { "Subi na prateleira mais alta só para provar que podia. Lá de cima dá para ver tudo, inclusive a mão que vem descendo.", fase = "jovem" },
                { "Todo autor constrói a queda devagar, e {autor} não deve ser exceção. Eu reconheço o método: é o mesmo das faxinas de fim de ano.", fase = "adulta" },
                { "Estou chegando ao último ato. Já sei o desfecho, já perdoei quase todo mundo e ainda não perdoei a vassoura.", fase = "ancia" },
                { "Tudo o que faço para sobreviver me deixa mais visível. Isso tem nome: {lente}." },
                { "“{livro}” vai acabar, eu vou comer a última página, e alguém vai chamar isso de dano, não de desfecho." },
                { "Este livro caminha para o lado {de_tema} desde a primeira página, e todo mundo finge surpresa. Eu não finjo. Moro no fim dos livros." },
                { "Morrer de fome numa biblioteca. Bom epitáfio." },
                -- novas (rascunhos de 29/10/2026, cartoes/rascunhos/influencias)
                { "Minha mãe chorou quando eu nasci. Disse que era de alegria. Mentiu. Era de conhecimento.", fase = "ninfa" },
                { "Uma traça antiga leu o meu futuro no padrão do mofo. Só disse para eu comer enquanto posso.", fase = "ninfa" },
                { "Meu primeiro erro foi gostar da luz. Toda traça comete esse erro uma vez. Algumas, só uma.", fase = "ninfa" },
                { "Meu irmão gostava da janela. A janela não gostava dele.", fase = "ninfa", curta = "Meu irmão gostava da janela. Ela não dele." },
                { "Pensei que a estante era o mundo inteiro e que o mundo inteiro era seguro. Primeira ilusão.", fase = "ninfa" },
                { "As traças velhas sempre avisam: “não vá”. Ninguém escuta. É por isso que elas são velhas e as outras não.", fase = "ninfa" },
                { "Me gabei de ter enfrentado o gato. Na semana seguinte, ele me lembrou quem manda.", fase = "jovem" },
                { "Sei que o meu defeito vai me matar: a curiosidade. Mesmo sabendo, continuo curiosa. Isso também é tragédia.", fase = "jovem" },
                { "Achei o esconderijo perfeito: uma caixa fechada. Era a caixa da doação.", fase = "jovem" },
                { "Ela mora na prateleira da luz. Eu, na da sombra. Na tragédia, o amor sempre mora longe.", fase = "jovem" },
                { "Ignorei o primeiro aviso, o segundo e o terceiro. No quarto, já era tarde para aviso.", fase = "jovem" },
                { "Madrugada: a hora em que todos os finais ficam evidentes.", quando = "noite", fase = "jovem" },
                { "Felicidade completa. Já sei: é a cena antes do terceiro ato.", quando = "feliz", fase = "jovem", curta = "Felicidade completa. Lá vem o terceiro ato." },
                { "Pele nova, destino velho.", quando = "muda", fase = "jovem" },
                { "Já sei o fim de quase tudo. Isso não me salva de nada. Me dá só um lugar melhor na plateia.", fase = "adulta" },
                { "Agora sou eu que aviso as jovens. Elas não escutam. Viramos coro, que é o que sobra de quem viu demais.", fase = "adulta" },
                { "Toda vez que uma traça se acha imortal, eu tiro a antena da frente e espero.", fase = "adulta" },
                { "Tentei mudar de livro para fugir do destino. O destino trocou de livro junto.", fase = "adulta" },
                { "Toda tragédia tem um culpado. Às vezes é o destino. Às vezes sou eu.", fase = "adulta" },
                { "Já decidi a minha última frase. Não conto. Uma traça precisa de algum suspense.", fase = "adulta" },
                { "A estante é um palco de madeira com data de demolição.", fase = "adulta" },
                { "Triste como um coro que ninguém aplaude.", quando = "triste", fase = "adulta" },
                { "Na minha idade, cada dia é um ato extra que o autor esqueceu de cortar.", fase = "ancia" },
                { "A sabedoria chega como as cartas nas tragédias: depois do enterro.", fase = "ancia" },
                { "Perdoei o gato, o aspirador e a umidade. A vassoura, não. Toda tragédia precisa de uma mágoa que fica.", fase = "ancia" },
                { "Sei que vou acabar numa página qualquer, achatada entre duas palavras. Espero que pelo menos sejam bonitas.", fase = "ancia" },
                { "O coro das tragédias é sempre de velhos. Agora entendo por quê.", fase = "ancia" },
                { "Noite comprida, fim perto. Fico ouvindo a casa como quem ouve o próprio coração no último ato.", quando = "noite", fase = "ancia" },
                { "Quero morrer comendo. É o único fim digno para uma traça.", fase = "ancia", curta = "Quero morrer comendo. Fim digno de traça." },
                { "Esta casa é um palco: a estante é o cenário, a vassoura é o destino e eu sou a figurante que insiste em ter fala." },
                { "Toda vez que {personagem} acredita que vai dar certo, eu como mais devagar. Para adiar." },
                { "Queria avisar {personagem}. As traças sempre querem avisar. Ninguém escuta as traças." },
                { "Fico com o coração apertado toda vez que {personagem} sorri. Conheço o gênero." },
                { "Se {personagem} soubesse o que eu sei sobre livros, pararia de ler." },
                { "Desde a primeira página de “{livro}”, sinto o cheiro do fim. É assim que se reconhece uma tragédia." },
                { "A ironia de “{livro}” é que todo mundo vê o desastre chegando, menos quem vai sofrer." },
                { "Comer “{livro}” é comer devagar uma sentença." },
                { "Admiro {autor} pela crueldade calma. As melhores tragédias são escritas com paciência." },
                { "{autor} não salva ninguém. Mas também não abandona." },
                { "{evento}: o primeiro degrau de uma escada que só desce." },
                { "Depois de {evento}, alguém disse “agora vai dar certo”. Eu parei de comer." },
                { "Terminei “{anterior}” chorando. Este vai pelo mesmo caminho, e eu vou junto." },
                { "Vi a faxina de hoje como {lente}: um final que todos previam e ninguém evitou." },
                { "“{palavra}” aparece de novo. Nas tragédias, a palavra que volta é o destino batendo na porta." },
                { "Toda história {de_tema} termina do mesmo jeito. Leio para ver como cada uma demora." },
                { "Vi você parar antes do último capítulo. Eu também paro. Algumas páginas a gente não quer comer." },
                { "Sinto a sua mão apertar a capa quando a história piora. Somos a mesma plateia." },
                { "Você não sabe ainda. Eu sei. É duro ser a traça que sabe." },
                { "Estou com fome. Sei onde tem comida. Sei também quem guarda. Vou mesmo assim.", quando = "fome" },
                { "Barriga cheia, guarda baixa. As tragédias adoram essa combinação.", quando = "cheia" },
                { "A noite desce como uma cortina sobre a estante. Ninguém aplaude.", quando = "noite" },
                { "Triste como quem já leu o último capítulo.", quando = "triste" },
                { "A vassoura não é má. É o destino de cabo de madeira. Faz o que tem que fazer." },
                { "A traça que ri da vassoura é sempre a primeira a ser varrida." },
                { "Aqui jaz uma traça que sabia o fim e comeu até lá." },
                { "A tragédia não é surpresa. É repetição com dor nova." },
                { "Sei como termina. Fico até o fim. É o que nos diferencia das cadeiras." },
                -- fim das novas
            },
            lentes = { "uma queda anunciada", "um terceiro ato sem intervalo", "um erro fatal" },
            fechos = { "Estava escrito.", "O coro já sabia.", "E não havia saída." },
