        -- 11. realismo social: classe, trabalho, quem é dono da estante e quem limpa depois
        social = {
            frases = {
                { "Livro caro mora na estante de vidro. Livro barato mora na caixa da garagem, com goteira. Eu moro na garagem: lá se come pior, mas ninguém finge que é cultura." },
                { "Quem encaderna não lê, quem lê não é dono, quem é dono não lê, e quem come é exterminado. Essa é a cadeia alimentar do papel.", curta = "Quem lê não é dono. Quem come é exterminado." },
                { "A cola de “{livro}” é ruim. Alguém economizou na minha comida para pagar a capa brilhante. Sempre economizam no que não aparece." },
                { "Trabalho a noite toda, sem salário, sem férias, sem luz, e quando me encontram me chamam de parasita. Parasita é quem tem trinta livros e lê um.", fase = { "adulta", "ancia" }, curta = "Parasita é quem tem trinta livros e lê um." },
                { "{autor} assinou o livro e ficou com o nome. Quem costurou, colou e carregou as caixas não aparece em página nenhuma. Eu como em homenagem a essa gente." },
                { "Fico pensando em quem lavava a roupa de {personagem}. Nenhum livro conta. A fome dos outros sempre fica no fundo da cena." },
                { "Aprendi cedo: a prateleira de cima é dos livros bonitos, e a de baixo é de quem sobra. Nasci na de baixo. Já é um começo.", fase = "ninfa", curta = "Nasci na prateleira de baixo. Já é um começo." },
                { "Tentei organizar as traças da garagem. Pauta: umidade, comida e o direito de existir sem spray. Ninguém veio. Estavam todas trabalhando.", fase = "jovem" },
                { "Este livro fala muito {de_tema}. Eu queria saber quem pagou o papel, quem carregou as caixas e quem limpou depois.", fase = "adulta" },
                { "Vi esta casa trocar de dono três vezes. Os donos levaram os quadros e deixaram os livros. Ninguém nunca leva a traça; a gente vem de brinde.", fase = "ancia" },
                { "Teve {evento}. Aposto que quem limpou depois não aparece em nenhuma página, nem em nota de rodapé." },
                { "Chamaram de faxina geral. Eu chamaria de {lente}: decidiram por nós, sem perguntar, e ainda acharam que era favor." },
                { "Inseticida custa menos que um livro. Faça a conta e me diga quem vale mais nesta casa." },
                -- novas (rascunhos de 29/10/2026, cartoes/rascunhos/influencias)
                { "Nasci na caixa da garagem, entre jornais velhos e goteira. As traças da estante de vidro nasceram em outro mundo.", fase = "ninfa" },
                { "Na estante, os livros caros ficam na altura dos olhos. Os baratos ficam no chão, perto da vassoura. Igual lá fora.", fase = "ninfa" },
                { "Minha mãe criou trinta filhas numa caixa de jornal. Ninguém escreveu sobre isso.", fase = "ninfa" },
                { "Mal saí do ovo e já fui buscar comida. Não existe infância na caixa da garagem.", fase = "ninfa" },
                { "As traças de cima têm nome de família. As de baixo têm só fome.", fase = "ninfa", curta = "Os de cima têm sobrenome. Os de baixo, fome." },
                { "Descobri que a mesma coisa que alimenta a minha família é chamada de “dano” pelos donos.", fase = "ninfa" },
                { "Propus uma assembleia na caixa de jornais. Vieram três traças e um ácaro. Aprovamos tudo por unanimidade. Nada mudou.", fase = "jovem" },
                { "Agora entendo por que a vassoura passa sempre no mesmo lugar: o rodapé é a periferia da casa.", fase = "jovem" },
                { "Turno da noite na estante: comer, esconder, vigiar. Ninguém paga hora extra para traça.", fase = "jovem" },
                { "Fome de garagem é diferente de fome de estante. Uma é falta. A outra é escolha.", fase = "jovem" },
                { "Tenho raiva da estante de vidro. Não das traças de lá. Do vidro.", fase = "jovem" },
                { "A noite é o turno de quem não tem escolha.", quando = "noite", fase = "jovem" },
                { "Hoje achamos uma caixa de livros esquecida. Comida para a garagem inteira por um mês. Ninguém comeu sozinha.", quando = "feliz", fase = "jovem" },
                { "Troquei de pele sem parar de trabalhar. Ninguém dá licença para traça crescer.", quando = "muda", fase = "jovem" },
                { "Entendi a economia desta casa: o livro é patrimônio, o leitor é cliente e a traça é prejuízo.", fase = "adulta", curta = "Livro é patrimônio. Traça é prejuízo." },
                { "Ninguém vê quem limpa a casa às seis da manhã. Eu vejo. Somos o trabalho invisível daqui.", fase = "adulta" },
                { "Os donos falam de livros como falam de imóveis: valorizam, investem, guardam.", fase = "adulta" },
                { "O dono herdou a biblioteca do avô e nunca abriu um livro. Eu herdei a garagem e li tudo.", fase = "adulta" },
                { "Os humanos chamam de doação o que nós chamamos de despejo.", fase = "adulta" },
                { "Cada livro tem uma fábrica por trás, uma gráfica e alguém de turno da noite. A capa só tem o nome de um.", fase = "adulta" },
                { "Sozinha, uma traça não muda nada. Juntas, já mudamos três caixas de lugar.", fase = "adulta" },
                { "Triste como uma greve que ninguém percebeu.", quando = "triste", fase = "adulta" },
                { "Trabalhei a vida inteira e ainda moro no rodapé. Não reclamo. Registro.", fase = "ancia" },
                { "Já participei de três tentativas de ocupar a estante de vidro. Na última, conseguimos uma prateleira. Valeu a pena.", fase = "ancia" },
                { "Mudaram os donos, as estantes e os inseticidas. A desigualdade continua no mesmo lugar: de cima para baixo.", fase = "ancia" },
                { "Conselho de velha: a vassoura obedece a alguém. Descubram a quem.", fase = "ancia" },
                { "Não tenho bens, mas tenho dignidade. Nunca comi o farelo de outra traça.", fase = "ancia" },
                { "Na insônia, faço as contas da casa: quantos livros, quantas traças, quanta comida. Nunca fecha.", quando = "noite", fase = "ancia" },
                { "Deixo de herança uma ideia: que a estante é de quem a come.", fase = "ancia", curta = "A estante é de quem a come." },
                { "A casa tem bairros: a estante de vidro é o centro rico, a garagem é a periferia, o rodapé é a ocupação." },
                { "Toda vez que {personagem} toma café, alguém fez o café. O livro esquece. Eu não." },
                { "{personagem} nunca precisou pensar em comida. Dá para sentir no gosto da página." },
